import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"Z","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/z.md","filePath":"glossaire-a-z/z.md"}'),t={name:"glossaire-a-z/z.md"};function s(l,e,i,d,u,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h1><h2 id="zero-knowledge-proofs-zkps-fr-preuves-a-divulgation-nulle-de-connaissance" tabindex="-1">Zero-Knowledge Proofs (ZKPs) (fr : Preuves à divulgation nulle de connaissance) <a class="header-anchor" href="#zero-knowledge-proofs-zkps-fr-preuves-a-divulgation-nulle-de-connaissance" aria-label="Permalink to &quot;Zero-Knowledge Proofs (ZKPs) (fr : Preuves à divulgation nulle de connaissance)&quot;">​</a></h2><p>Des techniques cryptographiques qui permettent à une partie de prouver qu’une affirmation est vraie sans révéler les informations secrètes qui la justifient.</p><p>→ <a href="https://developers.cardano.org/docs/developers/curriculum/smart-contracts/advanced/zero-knowledge/" target="_blank" rel="noreferrer">Cardano Developer Portal — Zero-Knowledge Proofs</a></p><h2 id="zkrollup" tabindex="-1">zkRollup <a class="header-anchor" href="#zkrollup" aria-label="Permalink to &quot;zkRollup&quot;">​</a></h2><p>Une solution de mise à l’échelle de couche 2 (<em>Layer 2</em>) qui regroupe plusieurs transactions hors chaîne et utilise une preuve de validité vérifiée sur la chaîne principale pour démontrer que les opérations regroupées respectent les règles définies.</p><p>Sur Cardano, <strong>zkFold Rollup est une solution de mise à l’échelle en développement</strong> qui utilise une preuve à divulgation nulle de connaissance pour vérifier plusieurs transactions regroupées. Il convient donc de distinguer cette initiative en développement d’une fonctionnalité native déjà intégrée au protocole de base de Cardano.</p><p>→ <a href="https://cardano.org/layer-2/" target="_blank" rel="noreferrer">Cardano.org — Layer 2 : solutions de mise à l’échelle</a></p><p>→ <a href="https://github.com/zkFold/zkfold-cardano" target="_blank" rel="noreferrer">zkFold — Intégration de technologies ZK à Cardano</a></p>',9)])])}const h=r(t,[["render",s]]);export{f as __pageData,h as default};
